var config
if (typeof(require) != "undefined") {
    var {
        ipcRenderer,
        desktopCapturer,
        remote
    } = require("electron")
    var win = remote.getCurrentWebContents()
    var path = require('path')
    var os = require('os')
    var fs = require('fs')
    var homedir = os.homedir()
    
    // Enhanced configuration loader supporting both config.js and config.json
    function loadEnhancedConfig() {
        const configJsonPath = path.join(homedir, 'clessapp', 'config.json')
        const configJsPath = path.join(homedir, 'clessapp', 'config.js')
        
        try {
            // Try config.json first (enhanced format)
            if (fs.existsSync(configJsonPath)) {
                const configData = JSON.parse(fs.readFileSync(configJsonPath, 'utf8'))
                console.log('eCLESS: Loaded enhanced configuration from config.json')
                return configData
            }
            
            // Fallback to config.js (legacy format)
            if (fs.existsSync(configJsPath)) {
                delete require.cache[require.resolve(configJsPath)]
                const oldConfig = require(configJsPath)
                console.log('eCLESS: Loaded legacy configuration from config.js')
                
                // Convert to enhanced format for compatibility
                return {
                    hostserver: oldConfig.hostserver,
                    id: oldConfig.id,
                    mode: oldConfig.mode,
                    corsproxy: oldConfig.corsproxy,
                    autostartup: oldConfig.autostartup,
                    autoStartup: oldConfig.autostartup === 'Y',
                    serialkey: oldConfig.serialkey,
                    timeout: oldConfig.timeout || 10000,
                    brightness: 75,
                    fullscreenMode: true,
                    _legacy: true
                }
            }
            
            throw new Error('No configuration file found')
        } catch (error) {
            console.error('eCLESS: Error loading configuration:', error)
            // Return default config
            return {
                hostserver: 'https://cless4.closed-loop.biz/demo',
                id: '10',
                mode: 'online',
                corsproxy: 'N',
                autostartup: 'Y',
                autoStartup: true,
                serialkey: '1d74f3eda4dd9d1065a6216c84c27d67301779b76996dc867f4403d48f9ad91e',
                timeout: 10000,
                brightness: 75,
                fullscreenMode: true,
                _default: true
            }
        }
    }
    
    config = loadEnhancedConfig()
}